using System;using System.IO;using System.Security.Cryptography;using Game.Runtime;
internal static class SourcePinnedFileOwnerControls {
 static void Require(bool value,string why){if(!value)throw new Exception(why);} static void Throws(Action action,string why){try{action();}catch(Exception){return;}throw new Exception(why);}
 static int Main(){string root=Path.Combine("/private/tmp","warline-pin-controls-"+Guid.NewGuid().ToString("N"));try{
 Environment.SetEnvironmentVariable("WARLINE_PINNED_ROOT_ORIGINAL",null);Environment.SetEnvironmentVariable("WARLINE_PINNED_ROOT_LOCAL",null);Environment.SetEnvironmentVariable("WARLINE_PINNED_ROOT_MAP",null);Directory.CreateDirectory(root);string local=Path.Combine(root,"local"),old=Path.Combine(root,"historical");Directory.CreateDirectory(local);Directory.CreateDirectory(old);string path=Path.Combine(local,"payload");byte[] value={1,2,3,4};File.WriteAllBytes(path,value);string hash;using(var sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(value)).Replace("-","").ToLowerInvariant();
 Require(AutonomousWorld.PinnedFile(path,hash,4).Length==4,"direct read");AutonomousWorld.VerifyPinnedFile(path,hash,4);Throws(()=>AutonomousWorld.PinnedFile(path,new string('0',64),4),"wrong digest accepted");Throws(()=>AutonomousWorld.VerifyPinnedFile(path,hash,3),"limit accepted");Throws(()=>AutonomousWorld.ResolvePinnedPath("relative"),"relative accepted");
 Environment.SetEnvironmentVariable("WARLINE_PINNED_ROOT_ORIGINAL",old);Environment.SetEnvironmentVariable("WARLINE_PINNED_ROOT_LOCAL",local);string historical=Path.Combine(old,"payload");File.WriteAllBytes(historical,value);
#if WARLINE_SOURCE_RELOCATABLE_PINNED_INPUTS
 Require(AutonomousWorld.PinnedMappingActive&&AutonomousWorld.ResolvePinnedPath(historical)==path,"relocation resolution");
 Throws(()=>AutonomousWorld.ResolvePinnedPath(Path.Combine(old,"..","historical","payload")),"noncanonical mapped path accepted");
 Environment.SetEnvironmentVariable("WARLINE_PINNED_ROOT_LOCAL",Path.Combine(old,"nested"));Directory.CreateDirectory(Path.Combine(old,"nested"));Throws(()=>AutonomousWorld.ResolvePinnedPath(historical),"overlapping roots accepted");Environment.SetEnvironmentVariable("WARLINE_PINNED_ROOT_LOCAL",local);
 string link=Path.Combine(root,"alias");var proc=System.Diagnostics.Process.Start("/bin/ln", "-s "+local+" "+link);proc.WaitForExit();Require(proc.ExitCode==0,"symlink setup");Environment.SetEnvironmentVariable("WARLINE_PINNED_ROOT_LOCAL",link);Throws(()=>AutonomousWorld.ResolvePinnedPath(historical),"symlink root accepted");Environment.SetEnvironmentVariable("WARLINE_PINNED_ROOT_LOCAL",local);
 Environment.SetEnvironmentVariable("WARLINE_PINNED_ROOT_MAP","[]");Throws(()=>AutonomousWorld.ResolvePinnedPath(historical),"conflicting mappings accepted");Environment.SetEnvironmentVariable("WARLINE_PINNED_ROOT_MAP",null);Require(AutonomousWorld.PinnedFile(historical,hash,4).Length==4,"relocation pinned read");AutonomousWorld.VerifyPinnedFile(historical,hash,4);File.WriteAllBytes(path,new byte[]{1,2,3,5});Throws(()=>AutonomousWorld.VerifyPinnedFile(historical,hash,4),"relocated drift accepted");
#else
 Environment.SetEnvironmentVariable("WARLINE_PINNED_ROOT_MAP","not-json");Require(!AutonomousWorld.PinnedMappingActive&&AutonomousWorld.ResolvePinnedPath(historical)==historical,"legacy ignores all mapping env");File.WriteAllBytes(path,new byte[]{1,2,3,5});Require(AutonomousWorld.PinnedFile(historical,hash,4).Length==4,"legacy direct read");File.WriteAllBytes(historical,new byte[]{1,2,3,5});Throws(()=>AutonomousWorld.VerifyPinnedFile(historical,hash,4),"legacy direct drift accepted");
#endif
 Console.WriteLine("[SourcePinnedFileOwnerControls] result=Passed direct=1 bounds=1 hash=1 profile_mapping=1 drift=1");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{Environment.SetEnvironmentVariable("WARLINE_PINNED_ROOT_ORIGINAL",null);Environment.SetEnvironmentVariable("WARLINE_PINNED_ROOT_LOCAL",null);Environment.SetEnvironmentVariable("WARLINE_PINNED_ROOT_MAP",null);if(Directory.Exists(root))Directory.Delete(root,true);}}
}
